package net.minecraft.util;public class MovingObjectPosition{public enum MovingObjectType{BLOCK,ENTITY}public MovingObjectType typeOfHit;public net.minecraft.entity.Entity entityHit;public int sideHit,blockX,blockY,blockZ;public MovingObjectPosition(net.minecraft.entity.Entity e){typeOfHit=MovingObjectType.ENTITY;entityHit=e;}public MovingObjectPosition(int side,int x,int y,int z){typeOfHit=MovingObjectType.BLOCK;sideHit=side;blockX=x;blockY=y;blockZ=z;}}
